import { chmod, mkdir, writeFile } from 'node:fs/promises'
import { execFile } from 'node:child_process'
import { join } from 'node:path'

/**
 * Hand a shell snippet to the user's own terminal so they press Enter themselves.
 * The snippet is always generated by lib/keygen.js from validated fields — this
 * module never accepts free-form commands from the browser.
 */
export async function runInTerminal({ script, dir, platform = process.platform }) {
  const text = String(script || '').trim()
  if (text === '') throw new Error('没有可执行的命令')
  if (text.includes('\u0000')) throw new Error('命令里含非法字符')

  if (platform === 'darwin') {
    const stamp = String(Date.now())
    const runDir = join(dir, '.tmp')
    await mkdir(runDir, { recursive: true })
    const file = join(runDir, `run-${stamp}.sh`)
    await writeFile(file, `#!/bin/sh\n${text}\nrm -f ${JSON.stringify(file)}\n`, { mode: 0o700 })
    await chmod(file, 0o700)
    const apple = [
      'tell application "Terminal" to activate',
      `tell application "Terminal" to do script ${JSON.stringify(`/bin/sh ${file}`)}`,
    ]
    await new Promise((resolve, reject) => {
      execFile('osascript', apple.flatMap((line) => ['-e', line]), { timeout: 15000 }, (error, _stdout, stderr) => {
        if (error) reject(new Error(`打开终端失败：${String(stderr || error.message).split('\n')[0]}`))
        else resolve()
      })
    })
    return { ok: true, how: 'Terminal.app', file }
  }

  if (platform === 'win32') {
    const escaped = text.replace(/"/g, '""')
    await new Promise((resolve, reject) => {
      execFile('powershell.exe', ['-NoProfile', '-Command', `Start-Process powershell -ArgumentList '-NoExit','-Command','${escaped}'`], { timeout: 15000 }, (error) => {
        if (error) reject(new Error('打开 PowerShell 失败'))
        else resolve()
      })
    })
    return { ok: true, how: 'PowerShell', file: '' }
  }

  // linux: try the first terminal emulator that exists
  const candidates = [
    ['gnome-terminal', ['--', 'bash', '-c', text]],
    ['konsole', ['-e', 'bash', '-c', text]],
    ['xterm', ['-e', 'bash', '-c', text]],
  ]
  for (const [bin, args] of candidates) {
    const done = await new Promise((resolve) => {
      execFile(bin, args, { timeout: 5000 }, (error) => resolve(!error))
    })
    if (done) return { ok: true, how: bin, file: '' }
  }
  throw new Error('没找到可用的终端程序（gnome-terminal / konsole / xterm）')
}
